begin;
do $$
declare token text:=encode(extensions.gen_random_bytes(32),'hex'); c uuid; first_m uuid; second_m uuid; final_m uuid;
  code1 text; code2 text; chosen int; final_choice int; snapshot jsonb; result jsonb; before_votes int;
begin
  insert into bracket_private.admin_sessions(token_hash,expires_at) values(bracket_private.secret_hash(token),now()+interval '1 hour');
  perform set_config('bracket.admin_token',token,true);
  c:=public.bracket_create_category('Random tie test',array['A','B','C','D']);
  code1:=public.bracket_issue_code('Tie voter 1'); code2:=public.bracket_issue_code('Tie voter 2');
  select id into first_m from bracket_private.matches where category_id=c and round=1 and position=0;
  select id into second_m from bracket_private.matches where category_id=c and round=1 and position=1;
  select id into final_m from bracket_private.matches where category_id=c and round=2;
  begin perform public.bracket_close_round(c); raise exception 'TEST: draft closed'; exception when others then if sqlerrm like 'TEST:%' then raise; end if; end;
  perform public.bracket_start(c);
  perform public.bracket_vote(code1,first_m,1); perform public.bracket_vote(code2,first_m,2);
  select jsonb_agg(to_jsonb(m) order by id) into snapshot from bracket_private.matches m where category_id=c;
  begin perform public.bracket_close_round(c); raise exception 'TEST: empty pair closed'; exception when others then if sqlerrm like 'TEST:%' then raise; end if; end;
  if snapshot is distinct from (select jsonb_agg(to_jsonb(m) order by id) from bracket_private.matches m where category_id=c) then raise exception 'TEST: failed close partially changed bracket'; end if;
  begin perform public.bracket_admin(token,'runoff',jsonb_build_object('p_category',c)); raise exception 'TEST: old runoff still works'; exception when others then if sqlerrm like 'TEST:%' then raise; end if; end;
  if (select ballot from bracket_private.matches where id=first_m)<>1 then raise exception 'TEST: runoff reset ballots'; end if;
  perform public.bracket_vote(code1,second_m,2); perform public.bracket_vote(code2,second_m,2);
  select count(*) into before_votes from bracket_private.votes;
  perform public.bracket_close_round(c);
  select winner into chosen from bracket_private.matches where id=first_m;
  if chosen is null or chosen not in (1,2) or not (select decided_randomly from bracket_private.matches where id=first_m) then raise exception 'TEST: random tie not resolved'; end if;
  if (select winner from bracket_private.matches where id=second_m)<>2 or (select decided_randomly from bracket_private.matches where id=second_m) then raise exception 'TEST: majority changed'; end if;
  if (select side_a from bracket_private.matches where id=final_m)<>(case chosen when 1 then 'A' else 'B' end) or (select side_b from bracket_private.matches where id=final_m)<>'D' then raise exception 'TEST: winners not propagated'; end if;
  if (select count(*) from bracket_private.votes)<>before_votes then raise exception 'TEST: votes changed'; end if;
  select x into result from jsonb_array_elements(public.bracket_state(null)->'categories') x where x->>'id'=c::text;
  if not exists(select 1 from jsonb_array_elements(result->'matches') x where x->>'id'=first_m::text and x->>'random'='true' and x->>'winner'=chosen::text) then raise exception 'TEST: public reason missing'; end if;
  begin perform public.bracket_close_round(c); raise exception 'TEST: empty final closed'; exception when others then if sqlerrm like 'TEST:%' then raise; end if; end;
  if (select winner from bracket_private.matches where id=first_m)<>chosen then raise exception 'TEST: rerolled previous tie'; end if;
  perform public.bracket_vote(code1,final_m,1); perform public.bracket_vote(code2,final_m,2);
  perform public.bracket_close_round(c);
  select winner into final_choice from bracket_private.matches where id=final_m;
  if (select status from bracket_private.categories where id=c)<>'finished' or not (select decided_randomly from bracket_private.matches where id=final_m) then raise exception 'TEST: tied final'; end if;
  begin perform public.bracket_close_round(c); raise exception 'TEST: finished closed again'; exception when others then if sqlerrm like 'TEST:%' then raise; end if; end;
  if (select winner from bracket_private.matches where id=final_m)<>final_choice then raise exception 'TEST: final rerolled'; end if;
  perform set_config('bracket.admin_token','',true);
  begin perform public.bracket_close_round(c); raise exception 'TEST: guest closure'; exception when insufficient_privilege then null; end;
  if has_function_privilege('anon','public.bracket_close_round(uuid)','execute') or has_function_privilege('authenticated','public.bracket_runoff(uuid)','execute') then raise exception 'TEST: direct admin grant'; end if;
end $$;
rollback;
select 'PASS: random ties, majority preserved, empty-pair rollback, persistent result and reason, final, no reroll, disabled runoff and guest denial. Test data rolled back.' as result;
